// sourceConnectionEntry maps connection items generated by mc-terrarium (source_connections_public.json).
type sourceConnectionEntry struct {
	Name       string `json:"name"`
	IPAddress  string `json:"ip_address"`
	IP         string `json:"ip"`
	SshPort    int    `json:"ssh_port"`
	Port       int    `json:"port"`
	User       string `json:"user"`
	PrivateKey string `json:"private_key"`
}

// externalSourceAccess holds ephemeral SSH credentials for an external source GPU VM.
type externalSourceAccess struct {
	NodeName   string
	Host       string
	Port       int
	Username   string
	PrivateKey string
}

// Clear wipes the in-memory PEM private key immediately after use.
func (a *externalSourceAccess) Clear() {
	if a == nil {
		return
	}
	a.PrivateKey = ""
}

// knownHostsMu serializes TOFU host key updates on the local known_hosts file.
var knownHostsMu sync.Mutex

// resolveConfigPath resolves a file path relative to CWD or the config file's parent directory.
func resolveConfigPath(cfgDir, rawPath string) string {
	trimmed := strings.TrimSpace(rawPath)
	if trimmed == "" || filepath.IsAbs(trimmed) {
		return trimmed
	}
	if _, err := os.Stat(trimmed); err == nil {
		return trimmed
	}
	if cfgDir != "" {
		aimxRootCandidate := filepath.Clean(filepath.Join(filepath.Dir(cfgDir), trimmed))
		if _, err := os.Stat(aimxRootCandidate); err == nil {
			return aimxRootCandidate
		}
		cfgDirCandidate := filepath.Clean(filepath.Join(cfgDir, trimmed))
		if _, err := os.Stat(cfgDirCandidate); err == nil {
			return cfgDirCandidate
		}
	}
	return trimmed
}

// resolveExternalSourceAccess loads SSH connection details from connectionsFile or explicit SourceConfig fields.
func resolveExternalSourceAccess(cfg TestConfig) (*externalSourceAccess, error) {
	src := cfg.Source
	if strings.TrimSpace(src.ConnectionsFile) != "" {
		connPath := resolveConfigPath(cfg.ConfigDir, src.ConnectionsFile)
		data, err := os.ReadFile(connPath)
		if err != nil {
			return nil, fmt.Errorf("failed to read source.connectionsFile %s: %w", connPath, err)
		}
		var entries []sourceConnectionEntry
		if err := json.Unmarshal(data, &entries); err != nil {
			return nil, fmt.Errorf("failed to parse source.connectionsFile %s: %w", connPath, err)
		}
		targetNode := strings.TrimSpace(src.NodeName)
		var available []string
		for _, e := range entries {
			available = append(available, e.Name)
			if strings.TrimSpace(e.Name) != targetNode {
				continue
			}
			host := firstNonEmpty(e.IPAddress, e.IP)
			port := e.SshPort
			if port <= 0 {
				port = e.Port
			}
			user := strings.TrimSpace(e.User)
			privKey := strings.TrimSpace(e.PrivateKey)
			if host == "" || port <= 0 || user == "" || privKey == "" {
				return nil, fmt.Errorf("incomplete SSH entry for node %q in %s (host=%q, port=%d, user=%q)", targetNode, connPath, host, port, user)
			}
			return &externalSourceAccess{
				NodeName:   targetNode,
				Host:       host,
				Port:       port,
				Username:   user,
				PrivateKey: privKey,
			}, nil
		}
		return nil, fmt.Errorf("node %q not found in %s (available nodes: %v)", targetNode, connPath, available)
	}

	keyPath := resolveConfigPath(cfg.ConfigDir, src.SshPrivateKeyPath)
	keyBytes, err := os.ReadFile(keyPath)
	if err != nil {
		return nil, fmt.Errorf("failed to read source.sshPrivateKeyPath %s: %w", keyPath, err)
	}
	privKey := strings.TrimSpace(string(keyBytes))
	if privKey == "" {
		return nil, fmt.Errorf("source.sshPrivateKeyPath %s is empty", keyPath)
	}
	nodeName := firstNonEmpty(src.NodeName, src.InfraID, src.SshHost)
	return &externalSourceAccess{
		NodeName:   nodeName,
		Host:       strings.TrimSpace(src.SshHost),
		Port:       src.SshPort,
		Username:   strings.TrimSpace(src.SshUsername),
		PrivateKey: privKey,
	}, nil
}

// resolveKnownHostsPath determines the local known_hosts file path used to verify or pin SSH host keys.
func resolveKnownHostsPath(cfg TestConfig) string {
	if custom := strings.TrimSpace(cfg.Source.SshKnownHostsPath); custom != "" {
		return resolveConfigPath(cfg.ConfigDir, custom)
	}
	statePath := resolveConfigPath(cfg.ConfigDir, cfg.Beetle.StateFile)
	dir := filepath.Dir(statePath)
	if dir == "" || dir == "." {
		dir = "testresult"
	}
	return filepath.Join(dir, ".aimx-known_hosts")
}

// newExternalHostKeyCallback builds a known_hosts verifier with Trust-On-First-Use support when strict mode is false.
func newExternalHostKeyCallback(cfg TestConfig) (ssh.HostKeyCallback, error) {
	khPath := resolveKnownHostsPath(cfg)
	if err := os.MkdirAll(filepath.Dir(khPath), 0o700); err != nil {
		return nil, fmt.Errorf("failed to create known_hosts directory for %s: %w", khPath, err)
	}
	if _, err := os.Stat(khPath); os.IsNotExist(err) {
		if cfg.Source.SshStrictHostKey {
			return nil, fmt.Errorf("known_hosts file %s does not exist and sshStrictHostKey is true", khPath)
		}
		if wErr := os.WriteFile(khPath, []byte(""), 0o600); wErr != nil {
			return nil, fmt.Errorf("failed to initialize known_hosts file %s: %w", khPath, wErr)
		}
	}

	return func(hostname string, remote net.Addr, key ssh.PublicKey) error {
		knownHostsMu.Lock()
		defer knownHostsMu.Unlock()

		cb, err := knownhosts.New(khPath)
		if err != nil {
			return fmt.Errorf("failed to load known_hosts %s: %w", khPath, err)
		}
		verifyErr := cb(hostname, remote, key)
		if verifyErr == nil {
			return nil
		}
		var keyErr *knownhosts.KeyError
		if !errors.As(verifyErr, &keyErr) || cfg.Source.SshStrictHostKey {
			return verifyErr
		}

		normHost := knownhosts.Normalize(hostname)
		newLine := knownhosts.Line([]string{normHost}, key) + "\n"
		if len(keyErr.Want) == 0 {
			f, openErr := os.OpenFile(khPath, os.O_APPEND|os.O_WRONLY|os.O_CREATE, 0o600)
			if openErr != nil {
				return fmt.Errorf("failed to append host key to %s: %w", khPath, openErr)
			}
			defer f.Close()
			_, writeErr := f.WriteString(newLine)
			return writeErr
		}

		fmt.Printf("⚠️  SSH host key changed for %s (re-provisioned cloud VM); updating %s\n", normHost, khPath)
		existingBytes, readErr := os.ReadFile(khPath)
		if readErr != nil {
			return readErr
		}
		var kept []string
		for _, line := range strings.Split(string(existingBytes), "\n") {
			trimmed := strings.TrimSpace(line)
			if trimmed == "" || strings.HasPrefix(trimmed, normHost+" ") || strings.HasPrefix(trimmed, normHost+",") {
				continue
			}
			kept = append(kept, line)
		}
		kept = append(kept, strings.TrimRight(newLine, "\n"))
		return os.WriteFile(khPath, []byte(strings.Join(kept, "\n")+"\n"), 0o600)
	}, nil
}

// execExternalSshCmd executes a shell script directly on the external source VM over SSH.
func execExternalSshCmd(cfg TestConfig, script string, printLive bool) (string, error) {
	access, err := resolveExternalSourceAccess(cfg)
	if err != nil {
		return "", err
	}
	defer access.Clear()

	signer, err := ssh.ParsePrivateKey([]byte(access.PrivateKey))
	if err != nil {
		return "", fmt.Errorf("failed to parse SSH private key for %s: %w", access.NodeName, err)
	}
	hostKeyCb, err := newExternalHostKeyCallback(cfg)
	if err != nil {
		return "", err
	}

	timeoutMin := cfg.Timing.RemoteCmdTimeoutMinutes
	if timeoutMin <= 0 {
		timeoutMin = 20
	}
	sshCfg := &ssh.ClientConfig{
		User:            access.Username,
		Auth:            []ssh.AuthMethod{ssh.PublicKeys(signer)},
		HostKeyCallback: hostKeyCb,
		Timeout:         15 * time.Second,
	}

	addr := net.JoinHostPort(access.Host, strconv.Itoa(access.Port))
	client, err := ssh.Dial("tcp", addr, sshCfg)
	if err != nil {
		return "", fmt.Errorf("SSH dial failed for %s (%s): %w", access.NodeName, addr, err)
	}
	defer client.Close()

	session, err := client.NewSession()
	if err != nil {
		return "", fmt.Errorf("failed to open SSH session on %s: %w", access.NodeName, err)
	}
	defer session.Close()

	stdoutPipe, err := session.StdoutPipe()
	if err != nil {
		return "", err
	}
	stderrPipe, err := session.StderrPipe()
	if err != nil {
		return "", err
	}

	wrappedCmd := "bash -s << 'AIMX_SSH_EOF'\n" + strings.ReplaceAll(script, "\r\n", "\n") + "\nAIMX_SSH_EOF"
	if err := session.Start(wrappedCmd); err != nil {
		return "", fmt.Errorf("failed to start SSH command on %s: %w", access.NodeName, err)
	}

	var stdoutBuilder, stderrBuilder strings.Builder
	var wg sync.WaitGroup
	var printMu sync.Mutex
	var lastPrinted string
	inProgress := false

	streamPipe := func(r io.Reader, isErr bool) {
		defer wg.Done()
		sc := bufio.NewScanner(r)
		sc.Buffer(make([]byte, 0, 64*1024), 1024*1024)
		for sc.Scan() {
			line := sc.Text()
			printMu.Lock()
			if isErr {
				stderrBuilder.WriteString(line)
				stderrBuilder.WriteString("\n")
			} else {
				stdoutBuilder.WriteString(line)
				stdoutBuilder.WriteString("\n")
			}
			if printLive {
				clean := sanitizeStreamLogLine(line)
				if clean != "" && clean != lastPrinted {
					lastPrinted = clean
					if isTransientProgressLine(clean) {
						fmt.Printf("\r   ⏳ %s\x1b[K", truncateRunes(clean, 96))
						inProgress = true
					} else {
						if inProgress {
							fmt.Print("\r\x1b[K")
							inProgress = false
						}
						fmt.Printf("   │ %s\n", clean)
					}
				}
			}
			printMu.Unlock()
		}
	}

	wg.Add(2)
	go streamPipe(stdoutPipe, false)
	go streamPipe(stderrPipe, true)

	doneCh := make(chan error, 1)
	go func() {
		wg.Wait()
		doneCh <- session.Wait()
	}()

	timer := time.NewTimer(time.Duration(timeoutMin) * time.Minute)
	defer timer.Stop()

	var waitErr error
	select {
	case waitErr = <-doneCh:
	case <-timer.C:
		_ = session.Close()
		_ = client.Close()
		return strings.TrimSpace(stdoutBuilder.String()), fmt.Errorf("SSH command timed out after %dm on %s", timeoutMin, access.NodeName)
	}

	if printLive && inProgress {
		fmt.Print("\r\x1b[K")
	}

	outStr := strings.TrimSpace(stdoutBuilder.String())
	if waitErr != nil {
		errStr := strings.TrimSpace(stderrBuilder.String())
		if errStr != "" {
			return outStr, fmt.Errorf("SSH command failed on %s: %v (stderr: %s)", access.NodeName, waitErr, errStr)
		}
		return outStr, fmt.Errorf("SSH command failed on %s: %w", access.NodeName, waitErr)
	}
	return outStr, nil
}

// runSourceCmd routes remote command execution on the Source VM via direct SSH or CB-Tumblebug SSE.
func runSourceCmd(tb *resty.Client, cfg TestConfig, auth AuthConfig, nodeID string, commands []string, printLive bool) (string, error) {
	if cfg.Source.isExternalSSH() {
		return execExternalSshCmd(cfg, strings.Join(commands, "\n"), printLive)
	}
	return execRemoteCmdSSE(tb, auth.TumblebugEndpoint, cfg.Source.NamespaceID, cfg.Source.InfraID, nodeID, commands, printLive)
}

// parseComposeModelEnv extracts LOCAL_MODEL and LOCAL_MODEL_EMBEDDINGS from a Docker Compose YAML file.
func parseComposeModelEnv(composeText string) (string, string) {
	var genModel, embModel string
	for _, rawLine := range strings.Split(composeText, "\n") {
		line := strings.TrimSpace(rawLine)
		line = strings.TrimPrefix(line, "-")
		line = strings.TrimSpace(line)
		if strings.HasPrefix(line, "#") {
			continue
		}
		if idx := strings.Index(line, "LOCAL_MODEL_EMBEDDINGS="); idx == 0 {
			val := strings.Trim(strings.TrimSpace(strings.TrimPrefix(line, "LOCAL_MODEL_EMBEDDINGS=")), `"'`)
			if val != "" {
				embModel = val
			}
		} else if idx := strings.Index(line, "LOCAL_MODEL="); idx == 0 {
			val := strings.Trim(strings.TrimSpace(strings.TrimPrefix(line, "LOCAL_MODEL=")), `"'`)
			if val != "" {
				genModel = val
			}
		} else if strings.HasPrefix(line, "LOCAL_MODEL_EMBEDDINGS:") {
			val := strings.Trim(strings.TrimSpace(strings.TrimPrefix(line, "LOCAL_MODEL_EMBEDDINGS:")), `"'`)
			if val != "" {
				embModel = val
			}
		} else if strings.HasPrefix(line, "LOCAL_MODEL:") {
			val := strings.Trim(strings.TrimSpace(strings.TrimPrefix(line, "LOCAL_MODEL:")), `"'`)
			if val != "" {
				genModel = val
			}
		}
	}
	return genModel, embModel
}

// resolveExternalAIServiceModels inspects <rootDir>/docker-compose.yml on an external SSH source when model tags are set to 'auto'.
func resolveExternalAIServiceModels(cfg *TestConfig) error {
	if cfg == nil || !cfg.Source.isExternalSSH() {
		return nil
	}
	composeFile := strings.TrimRight(cfg.AIService.RootDir, "/") + "/docker-compose.yml"
	out, err := execExternalSshCmd(*cfg, fmt.Sprintf("cat %q 2>/dev/null || true", composeFile), false)
	if err != nil {
		return fmt.Errorf("failed to inspect %s on external source VM: %w", composeFile, err)
	}
	liveGen, liveEmb := parseComposeModelEnv(out)

	if strings.EqualFold(strings.TrimSpace(cfg.AIService.ModelName), "auto") {
		if liveGen == "" {
			return fmt.Errorf("aiService.modelName is 'auto', but LOCAL_MODEL was not found in %s on external source VM", composeFile)
		}
		cfg.AIService.ModelName = liveGen
	} else if liveGen != "" && liveGen != cfg.AIService.ModelName {
		fmt.Printf("⚠️  Notice: Live source %s has LOCAL_MODEL=%q while config specifies aiService.modelName=%q\n",
			composeFile, liveGen, cfg.AIService.ModelName)
	}

	if strings.EqualFold(strings.TrimSpace(cfg.AIService.EmbeddingModel), "auto") {
		if cfg.AIService.isKotaemon() && liveEmb == "" {
			return fmt.Errorf("aiService.embeddingModel is 'auto', but LOCAL_MODEL_EMBEDDINGS was not found in %s on external source VM", composeFile)
		}
		cfg.AIService.EmbeddingModel = liveEmb
	} else if liveEmb != "" && cfg.AIService.EmbeddingModel != "" && liveEmb != cfg.AIService.EmbeddingModel {
		fmt.Printf("⚠️  Notice: Live source %s has LOCAL_MODEL_EMBEDDINGS=%q while config specifies aiService.embeddingModel=%q\n",
			composeFile, liveEmb, cfg.AIService.EmbeddingModel)
	}
	return nil
}

// enrichNodeFromExternalSource populates state.Source and OnpremInfra metadata from a live external SSH GPU VM.
func enrichNodeFromExternalSource(cfg TestConfig, state *MigrationState, baseInfra *onpremmodel.OnpremInfra) error {
	access, err := resolveExternalSourceAccess(cfg)
	if err != nil {
		return err
	}
	defer access.Clear()

	metaScript := `TOKEN=$(curl -sf --max-time 2 -X PUT "http://169.254.169.254/latest/api/token" -H "X-aws-ec2-metadata-token-ttl-seconds: 60" 2>/dev/null || true)
if [ -n "$TOKEN" ]; then
  echo "CLOUD_CSP=aws"
  echo "CLOUD_REGION=$(curl -sf --max-time 2 -H "X-aws-ec2-metadata-token: $TOKEN" http://169.254.169.254/latest/meta-data/placement/region 2>/dev/null || true)"
  echo "CLOUD_SPEC=$(curl -sf --max-time 2 -H "X-aws-ec2-metadata-token: $TOKEN" http://169.254.169.254/latest/meta-data/instance-type 2>/dev/null || true)"
  echo "CLOUD_IMAGE=$(curl -sf --max-time 2 -H "X-aws-ec2-metadata-token: $TOKEN" http://169.254.169.254/latest/meta-data/ami-id 2>/dev/null || true)"
fi`
	metaOut, _ := execExternalSshCmd(cfg, metaScript, false)
	var discCsp, discRegion, discSpec, discImage string
	for _, line := range strings.Split(metaOut, "\n") {
		parts := strings.SplitN(strings.TrimSpace(line), "=", 2)
		if len(parts) != 2 {
			continue
		}
		k, v := strings.TrimSpace(parts[0]), strings.TrimSpace(parts[1])
		switch k {
		case "CLOUD_CSP":
			discCsp = v
		case "CLOUD_REGION":
			discRegion = v
		case "CLOUD_SPEC":
			discSpec = v
		case "CLOUD_IMAGE":
			discImage = v
		}
	}

	infraLabel := firstNonEmpty(cfg.Source.InfraID, "ai-stack-testbed")
	csp := firstNonEmpty(cfg.Source.Csp, discCsp, "external")
	region := firstNonEmpty(cfg.Source.Region, discRegion, "external")
	specID := firstNonEmpty(discSpec, cfg.Source.SpecID, "external-gpu")
	imageID := firstNonEmpty(discImage, cfg.Source.ImageID, "ubuntu-gpu")

	if state.Source.PublicIP != access.Host || state.Source.SpecID != specID || state.Source.ModelName != cfg.AIService.ModelName {
		state.Source = EndpointMetrics{}
	}

	state.Source.InfraID = infraLabel
	state.Source.NodeID = access.NodeName
	state.Source.PublicIP = access.Host
	state.Source.SshKeyID = "external-ssh"
	state.Source.SshUsername = access.Username
	state.Source.Csp = csp
	state.Source.Region = region
	state.Source.SpecID = specID
	state.Source.ImageID = imageID
	state.Source.AppType = cfg.AIService.AppType
	state.Source.ModelName = cfg.AIService.ModelName
	state.Source.EmbeddingModel = cfg.AIService.EmbeddingModel
	state.Source.WebUIUrl = fmt.Sprintf("http://%s:%d", access.Host, cfg.AIService.activeAppPort())

	if baseInfra != nil && len(baseInfra.Nodes) > 0 {
		baseInfra.Nodes[0].MachineId = access.NodeName
		for i := range baseInfra.Network.IPv4Networks.DefaultGateways {
			baseInfra.Network.IPv4Networks.DefaultGateways[i].MachineId = access.NodeName
		}
		ensureFirewallPorts(&baseInfra.Nodes[0], 22, cfg.AIService.activeAppPort(), cfg.AIService.OllamaPort)
	}
	return nil
}

// ensureFirewallPorts guarantees that SSH and active AI service TCP ports are represented in NodeProperty.FirewallTable.
func ensureFirewallPorts(node *onpremmodel.NodeProperty, ports ...int) {
	existing := make(map[string]bool)
	for _, r := range node.FirewallTable {
		if strings.EqualFold(r.Direction, "inbound") && (strings.EqualFold(r.Protocol, "tcp") || r.Protocol == "*") {
			existing[strings.TrimSpace(r.DstPorts)] = true
		}
	}
	for _, p := range ports {
		if p <= 0 {
			continue
		}
		pStr := strconv.Itoa(p)
		if existing[pStr] || existing["*"] {
			continue
		}
		node.FirewallTable = append(node.FirewallTable, onpremmodel.FirewallRuleProperty{
			SrcCIDR:   "0.0.0.0/0",
			SrcPorts:  "*",
			DstCIDR:   "0.0.0.0/0",
			DstPorts:  pStr,
			Protocol:  "tcp",
			Direction: "inbound",
			Action:    "allow",
		})
		existing[pStr] = true
	}
}
